            lo,hi=min(ar,br),max(ar,br); l1,l2=min(ac,bc),max(ac,bc)
            for rr in range(lo+1,hi):
                for cc in range(l1+1,l2): ones.add((rr,cc))
        elif ac==bc:
            lo,hi=min(ar,br),max(ar,br); l1,l2=min(ac,bc),max(ac,bc)
            for rr in range(lo+1,hi):
                for cc in range(l1+1,l2): ones.add((rr,cc))
        elif (abs(ar-br)==abs(ac-bc)):
            step=(ar-br)//abs(ar-br),(ac-bc)//abs(ac-bc)
            rr,cc=ar,ac
            while (rr,cc)!=b:
                rr+=step[0]; cc+=step[1]; ones.add((rr,cc))
    return ones
