    for kind,keyf in [('main',lambda p:p[0]-p[1]),('anti',lambda p:p[0]+p[1])]:
        fam={}
        for mr,mc in M: fam.setdefault(keyf(mr,mc),[]).append((mr,mc))
        for pts in fam.values():
            if len(pts)<2: continue
            pts=sorted(pts, key=lambda q:(q[0] if kind=='main' else -(q[0]*-1))) 
            # proper sort: main diag order by r then c
            def keyf2(q): return (q[0],q[1]) if kind=='main' else (-(q[0]+W),q[1])
            pts.sort(key=keyf2)
            for a,b in zip(pts,pts[1:]):
                i=1
                while True:
                    rr=a[0]+(b[0]-a[0])*i//max(1,abs(b[0]-a[0])); cc=a[1]+(b[1]-a[1])*i//max(1,abs(b[1]-a[1]))
